function handler(event) {
  var request = event.request;
  var uri = request.uri;

  // Keep root request as-is (CloudFront defaultRootObject handles / -> /index.html)
  if (uri === '/') {
    return request;
  }

  // If no file extension, rewrite to folder index
  if (!uri.includes('.')) {
    if (uri.endsWith('/')) {
      request.uri = uri + 'index.html';
    } else {
      request.uri = uri + '/index.html';
    }
  }

  return request;
}
